      2: "A declaration from the marketing authorisation holder (and the ASMF holder, where applicable) that the starting material (specifications and analytical procedures) and the synthetic route, quality control procedures and specifications of the active substance and intermediate are the same as those already approved. For herbal active substances, a declaration that the geographical source, production of the herbal starting material/herbal substance and the manufacturing process are the same as those already approved.",
      3: "Either a TSE Ph. Eur. certificate of suitability for any new source of material or, where applicable, documentary evidence that the specific source of the TSE risk material has previously been assessed by the competent authority and shown to comply with the current Note for Guidance on Minimising the Risk of Transmitting Animal Spongiform Encephalopathy Agents via Human and Veterinary Medicinal Products, including manufacturer, species/tissues, country of origin, use and previous acceptance. For the centralised procedure, this should be included in an updated TSE table A (and B, if relevant).",
      4: "Batch analysis data (in a comparative tabular format) for at least two batches (minimum pilot scale) (or 3 batches, unless otherwise justified, for biologicals) of the active substance/starting material from the current and proposed manufacturers/sites.",
      5: "A declaration by the qualified person (QP) of each manufacturing authorisation holder listed in the application where the active substance is used as a starting material, and by the QP responsible for batch release, that the active substance manufacturer(s) operate in compliance with the detailed guidelines on GMP for starting materials. A single declaration may be acceptable under certain circumstances (see the note under Q.II.b.1).",
      6: "Where relevant, a commitment of the manufacturer of the active substance to inform the marketing authorisation holder of any changes to the manufacturing process, specifications and analytical procedures of the active substance.",
      7: "For herbal starting material, a detailed comparison regarding specifications and critical quality attributes of the herbal starting material. For herbal active substance, a detailed comparison regarding specifications and critical quality attributes (e.g. for extracts: herbal starting material, physical state, extraction solvent, drug extract ratio, and a stepwise comparison of manufacturing steps in tabular format).",
      8: "For a herbal starting material supplier, a GACP declaration from the new supplier (and updated QP declaration if the new supplier is also involved in herbal active substance manufacture).",
      9: "Valid proof that the proposed site is GMP compliant for the manufacturing and/or testing operation(s) concerned: for a site within the EU/EEA, a copy of the current manufacturing authorisation or, where none exists, a GMP compliance certificate issued within the last 3 years (a reference to EudraGMP suffices); for a third country site with an MRA or similar GMP agreement in place, proof of GMP compliance issued within the last 3 years by the relevant local authority; for a third country site without such an agreement, a GMP certificate issued within the last 3 years by an EEA Member State (a reference to EudraGMP suffices).",
      10: "The analytical procedure transfer protocols in accordance with Eudralex Volume 4 Chapter 6 Article 6.39 (which pre-define the acceptance criteria), from the old site to the new site (or new test laboratory).",
